import React,{createContext,useContext,useLayoutEffect} from 'react';
import {AbsoluteFill,delayRender,continueRender,cancelRender,staticFile,useCurrentFrame,useVideoConfig} from 'remotion';
import {S,mix} from './theme';
export const FredHost=createContext({accent:'#85c4c4',background:'#f5f3eb',speed:1});
export const useHost=()=>useContext(FredHost);
export const useT=()=>useCurrentFrame()/useVideoConfig().fps*useHost().speed;
let ready:Promise<void>|undefined;
function Fonts(){useLayoutEffect(()=>{const h=delayRender('FredTalk adapter OFL font');ready??=(async()=>{const face=new FontFace('LW Fred SmileySans',`url(${staticFile('fredtalk/SmileySans-Oblique.ttf')})`);await face.load();(document.fonts as unknown as {add:(f:FontFace)=>void}).add(face);})();ready.then(()=>continueRender(h)).catch(cancelRender);},[]);return null;}
export function Frame({children}:{children:React.ReactNode}){const {width}=useVideoConfig(),host=useHost();return <AbsoluteFill style={{background:host.background,overflow:'hidden',fontFamily:'LW Fred SmileySans',fontSynthesis:'none',color:S.ink}}><Fonts/><div style={{position:'absolute',width:1920,height:1080,transform:`scale(${width/1920})`,transformOrigin:'0 0',overflow:'hidden'}}>{children}</div></AbsoluteFill>;}
export const textBase=(size:number,_weight=900,_family?:string):React.CSSProperties=>({fontFamily:'LW Fred SmileySans',fontWeight:400,fontSize:size,lineHeight:1.16,fontSynthesis:'none',whiteSpace:'nowrap'});
export function MacWindow({box,style,title}:{box:{x:number;y:number;w:number;h:number};style?:React.CSSProperties;title?:string}){const host=useHost(),bar=90,dot=24;return <div style={{position:'absolute',left:box.x,top:box.y,width:box.w,height:box.h,borderRadius:36,overflow:'hidden',background:S.windowBody,boxShadow:S.windowShadow,...style}}><div style={{height:bar,background:S.windowBar,display:'flex',alignItems:'center',gap:dot,paddingLeft:bar*.63,position:'relative'}}>{[host.accent,'#aaa','#eee'].map(c=><span key={c} style={{width:dot,height:dot,borderRadius:dot,background:c}}/>)}{title&&<div style={{position:'absolute',left:160,right:160,textAlign:'center',fontSize:bar*.36,color:'#b6b6bd'}}>{title}</div>}</div></div>;}
export type HandoffProps={enter?:'cut'|'fade'|'rise'|'grow';exit?:'none'|'recede'|'fade'|'cut'|'slide-left'|'slide-up';exitAt?:number};
export function Handoff({enter='cut',exit='none',exitAt,children}:HandoffProps&{children:React.ReactNode}){const t=useT(),{durationInFrames,fps}=useVideoConfig(),speed=useHost().speed;const at=exitAt??durationInFrames/fps*speed-.5,v=enter==='cut'?1:Math.max(0,Math.min(1,t/.45)),e=1-(1-v)**3,x=exit==='none'?0:exit==='cut'?(t>=at?1:0):Math.max(0,Math.min(1,(t-at)/.5)),xs=x*x*(3-2*x);let opacity=enter==='cut'?1:e,transform='',filter='';if(enter==='rise')transform+=`translateY(${(1-e)*40}px) `;if(enter==='grow')transform+=`scale(${mix(.94,1,e)}) `;if(exit==='recede'){transform+=`scale(${mix(1,.92,xs)}) `;filter=`blur(${xs*14}px)`;opacity*=1-xs;}if(exit==='fade'||exit==='cut')opacity*=1-xs;if(exit==='slide-left')transform+=`translateX(${-xs*1100}px) `;if(exit==='slide-up')transform+=`translateY(${-xs*700}px) `;if(exit==='slide-left'||exit==='slide-up')opacity*=1-xs*.9;return <div style={{position:'absolute',inset:0,opacity,transform:transform||undefined,filter:filter||undefined,transformOrigin:'960px 540px'}}>{children}</div>;}
export function Sfx(_props:{name:string;at:number;volume?:number;duration?:number}){return null;}
